import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {execFileSync} from 'node:child_process';
import {createHash} from 'node:crypto';
const roots=['app','components','hooks','data','lib','public','scripts','db','drizzle','.github','AGENTS.md','PUBLICATIE.md','VORMGEVING-VASTGEZET.md','docs/appearance-floor-20261031','docs/KLINK-DOCENTHANDLEIDING.md','vite.config.ts','next.config.ts','package.json','package-lock.json','wrangler.jsonc'];
const git=(...args)=>execFileSync('git',args,{maxBuffer:128e6}),sha=b=>createHash('sha256').update(b).digest('hex'),lines=b=>b.toString().trim().split('\n').filter(Boolean),sorted=a=>a.sort((a,b)=>a.localeCompare(b));
export function verifyKlink10SentencesRelease(read=readFileSync){
 const json=p=>JSON.parse(read(p)),dir='docs/klink10-sentences-20261102/',r=json('docs/klink-owner-release-ten-sentences-20261102.json');
 assert.equal(r.approvedBy,'Nico');assert.equal(r.ownerApproval,'standing-owner-approval');assert(r.publicationApproved&&r.existingAppearancePreserved&&r.progressPreserved);
 assert.equal(r.baselineSourceCommit,'eb6270430997e84ffbb3428d4f1fbdfe06e52546');assert.equal(r.liveSourceCommit,'eb6270430997e84ffbb3428d4f1fbdfe06e52546');git('merge-base','--is-ancestor',r.liveSourceCommit,r.baselineSourceCommit);git('merge-base','--is-ancestor',r.baselineSourceCommit,'HEAD');
 const changed=sorted([...new Set([...lines(git('diff','--name-only',r.baselineSourceCommit,'--',...roots)),...lines(git('ls-files','--others','--exclude-standard','--',...roots))])]);assert.deepEqual(changed,r.changedFiles);assert.deepEqual(sorted(Object.keys(r.files)),changed);
 const allowed=['components/product/package-exercise-browser.tsx','lib/sentence-answer.ts','data/klink-production-index.json','data/klink-production-instructions.json','scripts/test-sentence-answer.mjs','scripts/test-practice-chapters.mjs','scripts/check-sentence-round-titles-release-20261102.mjs','scripts/check-klink10-sentences-release-20261102.mjs','scripts/test-klink10-sentences-20261102.mjs','scripts/test-klink10-sentences-browser-20261102.mjs','scripts/test-klink10-sentences-media-20261102.mjs','scripts/test-klink10-sentences-access-20261102.mjs','scripts/test-klink10-sentences-release-20261102.mjs'];
 assert(changed.every(p=>allowed.includes(p)||p.startsWith('public/practice-content/klink10-sentences-20261102/')||p.startsWith('public/package-audio/klink10-sentences-20261102/')));assert.equal(git('diff','--name-only','--diff-filter=MD',r.baselineSourceCommit,'--','public').length,0,'Existing media must remain immutable');
 for(const[p,h]of Object.entries({...r.files,...r.evidenceFiles}))assert.equal(sha(read(p)),h,p);
 const m=json(dir+'import-manifest.json'),ids=new Set(m.newRows.map(x=>x.row.id));assert.equal(m.sourcePositions,220);assert.equal(m.blockedSourcePositions,10);assert.equal(ids.size,22);assert.deepEqual(json('data/klink-production-index.json').filter(x=>!ids.has(x.id)),JSON.parse(git('show',r.baselineSourceCommit+':data/klink-production-index.json')));
 for(const p of ['data/klink-word-listening-audio.json','data/klink-word-listening.json'])assert.deepEqual(json(p),JSON.parse(git('show',r.baselineSourceCommit+':'+p)));
 const oldInstructions=JSON.parse(git('show',r.baselineSourceCommit+':data/klink-production-instructions.json')),instructions=json('data/klink-production-instructions.json');assert.deepEqual(instructions.slice(0,oldInstructions.length),oldInstructions);assert.equal(instructions.length,oldInstructions.length+25);assert(instructions.slice(oldInstructions.length).every(x=>x.voiceId==='h6uBOiAjLKklte8hdYio'));
 for(const b of m.bundles){assert.equal(sha(read('public'+b.src)),b.sha256);assert(b.bytes<=3*1024*1024);}
 const seen=new Set();for(const{row,sha256}of m.newRows){assert.equal(sha(read('public'+row.url)),sha256);const bank=json('public'+row.url);assert.equal(bank.id,row.id);assert.equal(bank.exercises.length,10);for(const e of bank.exercises){assert(!seen.has(e.exerciseId));seen.add(e.exerciseId);assert(e.manualAdvance&&e.requiresExplicitCompletion);assert.equal(e.reviewEligible,false);assert.equal(e.independentReading,false);if(e.mode==='open-sentence')assert.equal(e.assessment,'participation');assert(!e.exerciseId.startsWith('SZ-ALFA-C-LLM-'));}}
 assert.equal(seen.size,220);const content=json(dir+'local/content.json');assert.equal(content.checks.length,220);assert(content.allPriorCollectionsAndWordModelsPreserved);
 const browser=json(dir+'local/browser.json');assert.equal(browser.checks.length,880);assert.deepEqual(browser.errors,[]);assert(browser.existingProgressPreserved);assert.equal(json(dir+'local/access.json').checks.length,16);
 const media=json(dir+'selected-media-verification.json');assert.equal(media.checks.length,Object.keys(m.newAudio).length+Object.keys(m.reusedAudio).length);assert(media.checks.every(c=>c.fullDecode));assert.equal(media.humanListening,false);
 const native=json(dir+'local/native-media.json');assert.equal(native.checks.length,media.checks.length*2);assert.equal(native.playerPlaybackChecks,6);const sources=json(dir+'source-recheck.json');assert.equal(sources.length,5);assert(sources.every(s=>s.fullTextUnchanged));
 const v=json(dir+'verification.json');assert(v.types&&v.lint&&v.wordAudioCoverage&&v.coreTests&&v.screensVisuallyReviewed&&v.existingViewControlsPreserved);assert.equal(v.humanListening,false);assert.equal(v.physicalDeviceTested,false);
 const backup=json(dir+'backup.json');assert(backup.fullReadback&&backup.zipIntegrity&&backup.driveId);assert.deepEqual(backup.files,r.files);assert.deepEqual(backup.evidenceFiles,r.evidenceFiles);return r;
}
export function readBeforeKlink10Sentences(file,r,read=readFileSync){return r.changedFiles.includes(file)?git('show',r.baselineSourceCommit+':'+file):read(file);}
